// @ts-nocheck
const Users={currentPage:1,pageSize:20,searchParams:{},async render(){document.getElementById("pageContent").innerHTML='\n            <div class="card">\n                <div class="card-header">\n                    <h3 class="card-title">Quản lý người dùng</h3>\n                </div>\n                <div class="card-body">\n                    <div class="search-box mb-3">\n                        <select class="form-control" id="searchType" style="width: 150px;">\n                            <option value="email">Email</option>\n                            <option value="id">ID</option>\n                        </select>\n                        <input type="text" class="form-control search-input" id="searchInput" \n                               placeholder="Nhập từ khóa tìm kiếm...">\n                        <button class="btn btn-primary" onclick="Users.search()">\n                            <i class="fas fa-search"></i> Tìm kiếm\n                        </button>\n                        <button class="btn btn-outline" onclick="Users.reset()">\n                            <i class="fas fa-redo"></i> Reset\n                        </button>\n                    </div>\n                    \n                    <div id="usersTable">\n                        <div class="loading-container">\n                            <div class="loading-spinner"></div>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        ',await Users.loadUsers()},async loadUsers(t=1){Users.currentPage=t;try{const t={page:Users.currentPage,limit:Users.pageSize,...Users.searchParams},n=await API.users.search(t);Users.renderTable(n)}catch(t){console.error("Failed to load users:",t),document.getElementById("usersTable").innerHTML='\n                <div class="alert alert-danger">\n                    Không thể tải danh sách người dùng\n                </div>\n            '}},renderTable(t){const{data:n,total:e,current:s,pageSize:r}=t,a=Math.ceil(e/r);if(!n||0===n.length)return void(document.getElementById("usersTable").innerHTML='\n                <div class="alert alert-info">\n                    Không tìm thấy người dùng nào\n                </div>\n            ');let i='\n            <div class="table-responsive">\n                <table class="data-table">\n                    <thead>\n                        <tr>\n                            <th>ID</th>\n                            <th>Email</th>\n                            <th>Gói dịch vụ</th>\n                            <th>Đã dùng</th>\n                            <th>Giới hạn</th>\n                            <th>Thiết bị</th>\n                            <th>Hạn dùng</th>\n                            <th>Hành động</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n        ';n.forEach((t=>{const n=App.formatBytes((t.u||0)+(t.d||0)),e=App.formatBytes(t.transfer_enable||0),s=t.plan_name||'<span class="text-muted">Không có</span>',r=t.expired_at?App.formatDate(t.expired_at):"-",a=t.expired_at&&t.expired_at>Date.now()/1e3?"text-success":"text-danger";i+=`\n                <tr>\n                    <td>${t.id}</td>\n                    <td>${t.email}</td>\n                    <td>${s}</td>\n                    <td>${n}</td>\n                    <td>${e}</td>\n                    <td>${t.alive_ip||0}</td>\n                    <td><span class="${a}">${r}</span></td>\n                    <td>\n                        <button class="btn btn-sm btn-primary" onclick="Users.viewDetails(${t.id})" title="Chi tiết">\n                            <i class="fas fa-eye"></i>\n                        </button>\n                        <button class="btn btn-sm btn-info" onclick="Users.copySubscribe('${t.subscribe_url}')" title="Copy link">\n                            <i class="fas fa-copy"></i>\n                        </button>\n                        <button class="btn btn-sm btn-warning" onclick="App.showQRCode('${t.subscribe_url}')" title="QR Code">\n                            <i class="fas fa-qrcode"></i>\n                        </button>\n                        <button class="btn btn-sm btn-danger" onclick="Users.resetSecurity(${t.id})" title="Reset Security">\n                            <i class="fas fa-shield-alt"></i>\n                        </button>\n                    </td>\n                </tr>\n            `})),i+="\n                    </tbody>\n                </table>\n            </div>\n        ",a>1&&(i+=App.createPagination(s,a,"Users.loadUsers")),i+=`\n            <div class="mt-3 text-muted">\n                Hiển thị ${(s-1)*r+1} - ${Math.min(s*r,e)} trong tổng số ${e} người dùng\n            </div>\n        `,document.getElementById("usersTable").innerHTML=i},search(){const t=document.getElementById("searchType").value,n=document.getElementById("searchInput").value.trim();Users.searchParams=n?{[t]:n}:{},Users.loadUsers(1)},reset(){document.getElementById("searchInput").value="",Users.searchParams={},Users.loadUsers(1)},copySubscribe(t){App.copyToClipboard(t)},async viewDetails(t){try{const n=(await API.users.getById(t)).data,e=`\n                <div class="user-details">\n                    <table class="detail-table">\n                        <tr>\n                            <td><strong>ID:</strong></td>\n                            <td>${n.id}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Email:</strong></td>\n                            <td>${n.email}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Số dư:</strong></td>\n                            <td>${App.formatCurrency(n.balance)}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Hoa hồng:</strong></td>\n                            <td>${App.formatCurrency(n.commission_balance)}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Gói dịch vụ:</strong></td>\n                            <td>${n.plan_id?`ID: ${n.plan_id}`:"Không có"}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Tốc độ:</strong></td>\n                            <td>${n.speed_limit||0} Mbps</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Thiết bị tối đa:</strong></td>\n                            <td>${n.device_limit||0}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Đã dùng:</strong></td>\n                            <td>${App.formatBytes((n.u||0)+(n.d||0))}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Giới hạn:</strong></td>\n                            <td>${App.formatBytes(n.transfer_enable||0)}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Ngày hết hạn:</strong></td>\n                            <td>${n.expired_at?App.formatDate(n.expired_at):"Không giới hạn"}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>UUID:</strong></td>\n                            <td style="word-break: break-all;">${n.uuid}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Token:</strong></td>\n                            <td style="word-break: break-all;">${n.token}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Trạng thái:</strong></td>\n                            <td>${n.banned?'<span class="text-danger">Đã khóa</span>':'<span class="text-success">Hoạt động</span>'}</td>\n                        </tr>\n                        <tr>\n                            <td><strong>Ngày đăng ký:</strong></td>\n                            <td>${App.formatDate(n.created_at)}</td>\n                        </tr>\n                    </table>\n                </div>\n                <style>\n                    .user-details { padding: 20px; }\n                    .detail-table { width: 100%; }\n                    .detail-table td { padding: 8px; border-bottom: 1px solid #eee; }\n                    .detail-table tr:last-child td { border-bottom: none; }\n                </style>\n            `;App.showModal(`Chi tiết người dùng #${t}`,e)}catch(t){App.showToast("error","Lỗi","Không thể tải thông tin người dùng")}},async resetSecurity(t){if(confirm("Bạn có chắc chắn muốn reset security cho user này?\n\nViệc này sẽ tạo mới UUID và token, làm mất hiệu lực tất cả subscription URLs cũ."))try{const n=await API.users.resetSecurity(t);if(n.data&&n.data.success){const e=n.data.new_subscribe_url,s=`\n                    <div class="reset-success">\n                        <div class="alert alert-success">\n                            <h5><i class="fas fa-check-circle"></i> Reset Security thành công!</h5>\n                            <p>UUID và token mới đã được tạo. Subscription URL cũ không còn hiệu lực.</p>\n                        </div>\n                        \n                        <div class="new-url-section">\n                            <label class="form-label"><strong>Subscription URL mới:</strong></label>\n                            <div class="input-group">\n                                <input type="text" class="form-control" id="newSubscribeUrl" value="${e}" readonly>\n                                <button class="btn btn-primary" onclick="App.copyToClipboard('${e}')">\n                                    <i class="fas fa-copy"></i> Copy\n                                </button>\n                            </div>\n                        </div>\n                        \n                        <div class="qr-section mt-3">\n                            <label class="form-label"><strong>QR Code mới:</strong></label>\n                            <div class="text-center">\n                                <img src="https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(e)}" \n                                     alt="QR Code" style="border: 1px solid #ddd; border-radius: 8px;">\n                            </div>\n                        </div>\n                    </div>\n                    \n                    <style>\n                        .reset-success { padding: 20px; }\n                        .input-group { display: flex; }\n                        .input-group input { flex: 1; margin-right: 10px; }\n                        .new-url-section, .qr-section { margin: 20px 0; }\n                    </style>\n                `,r='\n                    <button class="btn btn-primary" onclick="App.closeModal(this)">Đóng</button>\n                    <button class="btn btn-outline" onclick="Users.loadUsers(Users.currentPage)">\n                        <i class="fas fa-sync"></i> Tải lại danh sách\n                    </button>\n                ';App.showModal(`Reset Security thành công - User #${t}`,s,r)}else App.showToast("error","Lỗi","Reset security thất bại")}catch(t){App.showToast("error","Lỗi",t.message||"Không thể reset security")}}};